import { maskNonMarkup } from '../../mdx.js';
import type { FileRule, FileFinding } from '../../types.js';

const VOID_TAG = /<(br|hr|img)(?=[\s/>])((?:"[^"]*"|'[^']*'|\{[^{}]*\}|[^<>"'{}])*?)(\/?)>/g;

export const voidTags: FileRule = {
  id: 'void-tags',
  group: 'content',
  severity: 'error',
  scope: 'file',
  description: "self-close void HTML tags (<br>, <hr>, <img>); MDX can't parse them unclosed",
  raw: true,
  check: ({ content }) => {
    const masked = maskNonMarkup(content);
    const issues: FileFinding[] = [];
    for (const match of masked.matchAll(VOID_TAG)) {
      if (match[3]) continue;
      const start = match.index;
      const end = start + match[0].length;
      if (new RegExp(`^\\s*</${match[1]}\\s*>`).test(masked.slice(end))) continue;
      const before = content.slice(0, start).split('\n');
      issues.push({
        line: before.length,
        column: (before.pop()?.length ?? 0) + 1,
        message: `<${match[1]}> must be self-closed`,
        edit: {
          start,
          end,
          text: `${content.slice(start, end - 1).trimEnd()} />`,
        },
      });
    }
    return issues;
  },
};
